  "hp-nephron-schematic": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 300 200\" class=\"w-full\" role=\"img\" aria-label=\"A nephron: blood is filtered at Bowman&#x27;s capsule surrounding the glomerulus, the filtrate travels through the coiled tubule and loop of Henle where substances are reabsorbed, and the remaining fluid passes into the collecting duct as urine.\"><circle cx=\"62\" cy=\"60\" r=\"26\" class=\"fill-rose-100/60 stroke-rose-500 dark:fill-rose-900/30\" stroke-width=\"1.8\"></circle><circle cx=\"62\" cy=\"60\" r=\"13\" class=\"fill-rose-400/60 stroke-rose-600\" stroke-width=\"1.4\"></circle><text x=\"62\" y=\"22\" text-anchor=\"middle\" class=\"fill-rose-700 dark:fill-rose-300\" font-size=\"9.5\" font-weight=\"600\">Bowman’s capsule</text><text x=\"62\" y=\"100\" text-anchor=\"middle\" class=\"fill-slate-500\" font-size=\"8\">(filtration)</text><path d=\"M 88 60 C 130 50, 130 90, 150 90 C 180 90, 150 150, 185 150 C 215 150, 215 100, 235 100\" class=\"fill-none stroke-indigo-500\" stroke-width=\"3\"></path><text x=\"150\" y=\"74\" text-anchor=\"middle\" class=\"fill-indigo-700 dark:fill-indigo-300\" font-size=\"9\">Tubule</text><text x=\"172\" y=\"170\" text-anchor=\"middle\" class=\"fill-indigo-600 dark:fill-indigo-300\" font-size=\"8\">loop of Henle</text><text x=\"150\" y=\"120\" text-anchor=\"middle\" class=\"fill-slate-500\" font-size=\"8\">(reabsorption)</text><rect x=\"232\" y=\"95\" width=\"16\" height=\"80\" rx=\"4\" class=\"fill-amber-200/60 stroke-amber-600 dark:fill-amber-900/30\" stroke-width=\"1.6\"></rect><text x=\"240\" y=\"190\" text-anchor=\"middle\" class=\"fill-amber-700 dark:fill-amber-300\" font-size=\"8.5\">Urine</text></svg></div>",
  "hp-reflex-arc": "<div class=\"mx-auto max-w-md rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 320 110\" class=\"w-full\" role=\"img\" aria-label=\"The reflex arc flows in one direction: receptor to sensory neuron to spinal cord to motor neuron to effector. The signal is processed in the spinal cord, not the brain.\"><g><rect x=\"6\" y=\"18\" width=\"56\" height=\"34\" rx=\"6\" class=\"fill-sky-100/70 stroke-sky-600 dark:fill-sky-900/40\" stroke-width=\"1.6\"></rect><text x=\"34\" y=\"39\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"8.2\" font-weight=\"600\">Receptor</text><line x1=\"62\" y1=\"35\" x2=\"74\" y2=\"79\" class=\"stroke-slate-500\" stroke-width=\"1.6\" marker-end=\"url(#hp-arrow)\"></line></g><g><rect x=\"68\" y=\"62\" width=\"56\" height=\"34\" rx=\"6\" class=\"fill-indigo-100/70 stroke-indigo-600 dark:fill-indigo-900/40\" stroke-width=\"1.6\"></rect><text x=\"96\" y=\"83\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"8.2\" font-weight=\"600\">Sensory neuron</text><line x1=\"124\" y1=\"79\" x2=\"136\" y2=\"35\" class=\"stroke-slate-500\" stroke-width=\"1.6\" marker-end=\"url(#hp-arrow)\"></line></g><g><rect x=\"130\" y=\"18\" width=\"56\" height=\"34\" rx=\"6\" class=\"fill-rose-100/70 stroke-rose-600 dark:fill-rose-900/40\" stroke-width=\"1.6\"></rect><text x=\"158\" y=\"39\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"8.2\" font-weight=\"600\">Spinal cord</text><line x1=\"186\" y1=\"35\" x2=\"198\" y2=\"79\" class=\"stroke-slate-500\" stroke-width=\"1.6\" marker-end=\"url(#hp-arrow)\"></line></g><g><rect x=\"192\" y=\"62\" width=\"56\" height=\"34\" rx=\"6\" class=\"fill-indigo-100/70 stroke-indigo-600 dark:fill-indigo-900/40\" stroke-width=\"1.6\"></rect><text x=\"220\" y=\"83\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"8.2\" font-weight=\"600\">Motor neuron</text><line x1=\"248\" y1=\"79\" x2=\"260\" y2=\"35\" class=\"stroke-slate-500\" stroke-width=\"1.6\" marker-end=\"url(#hp-arrow)\"></line></g><g><rect x=\"254\" y=\"18\" width=\"56\" height=\"34\" rx=\"6\" class=\"fill-emerald-100/70 stroke-emerald-600 dark:fill-emerald-900/40\" stroke-width=\"1.6\"></rect><text x=\"282\" y=\"39\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"8.2\" font-weight=\"600\">Effector</text></g><defs><marker id=\"hp-arrow\" markerWidth=\"7\" markerHeight=\"7\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" class=\"fill-slate-500\"></path></marker></defs><text x=\"160\" y=\"106\" text-anchor=\"middle\" class=\"fill-slate-500\" font-size=\"8\">Processed in the spinal cord — not the brain (so it’s fast)</text></svg></div>",
  "hp-eye-cross-section": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 300 200\" class=\"w-full\" role=\"img\" aria-label=\"Cross-section of the eye: light enters through the cornea at the front, passes the pupil and lens, and forms an image on the retina lining the back of the eyeball.\"><circle cx=\"150\" cy=\"100\" r=\"78\" class=\"fill-white stroke-slate-400 dark:fill-slate-800\" stroke-width=\"1.6\"></circle><path d=\"M 150 22 A 78 78 0 0 1 150 178\" class=\"fill-none stroke-rose-500\" stroke-width=\"4\"></path><text x=\"244\" y=\"104\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"10\" font-weight=\"600\">Retina</text><text x=\"232\" y=\"118\" class=\"fill-slate-500\" font-size=\"8\">(image forms)</text><path d=\"M 72 78 A 30 30 0 0 0 72 122\" class=\"fill-sky-100/60 stroke-sky-600 dark:fill-sky-900/30\" stroke-width=\"2.4\"></path><text x=\"6\" y=\"70\" class=\"fill-sky-700 dark:fill-sky-300\" font-size=\"10\" font-weight=\"600\">Cornea</text><text x=\"2\" y=\"83\" class=\"fill-slate-500\" font-size=\"8\">(light enters)</text><ellipse cx=\"96\" cy=\"100\" rx=\"9\" ry=\"26\" class=\"fill-indigo-200/70 stroke-indigo-600 dark:fill-indigo-900/40\" stroke-width=\"1.6\"></ellipse><text x=\"80\" y=\"158\" class=\"fill-indigo-700 dark:fill-indigo-300\" font-size=\"9\">Lens</text><line x1=\"84\" y1=\"66\" x2=\"84\" y2=\"80\" class=\"stroke-amber-600\" stroke-width=\"3\"></line><line x1=\"84\" y1=\"120\" x2=\"84\" y2=\"134\" class=\"stroke-amber-600\" stroke-width=\"3\"></line><text x=\"40\" y=\"150\" class=\"fill-amber-700 dark:fill-amber-300\" font-size=\"8.5\">Iris / pupil</text><line x1=\"14\" y1=\"100\" x2=\"150\" y2=\"100\" class=\"stroke-yellow-500\" stroke-width=\"1.4\" stroke-dasharray=\"5 3\"></line><text x=\"150\" y=\"100\" class=\"fill-yellow-600\" font-size=\"8\" dx=\"2\" dy=\"-3\">light</text></svg></div>",
